import { supabase, configured } from './supabase.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={page:'dashboard',user:null,profile:null,catalogs:{},animals:[],selectedAnimal:null};
const nav=[['dashboard','bi-grid','Panel principal'],['animals','bi-heart','Animales'],['homes','bi-house-heart','Hogares temporales'],['adoptions','bi-house-check','Adopciones'],['expenses','bi-cash-stack','Gastos'],['sterilization','bi-clipboard2-pulse','Proyectos de esterilización'],['documents','bi-folder2-open','Documentos'],['reports','bi-bar-chart','Informes'],['settings','bi-gear','Configuración']];
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmtDate=v=>v?new Intl.DateTimeFormat('es-CL',{dateStyle:'medium'}).format(new Date(v+'T12:00:00')):'—';
const money=v=>new Intl.NumberFormat('es-CL',{style:'currency',currency:'CLP',maximumFractionDigits:0}).format(v||0);
const toast=(m,error=false)=>{const e=$('#toast');e.textContent=m;e.className='toast show'+(error?' error':'');setTimeout(()=>e.className='toast',3500)};
const fail=e=>{console.error(e);toast(e?.message||'Ocurrió un error.',true)};
const empty=(msg='No hay registros todavía.')=>`<div class="empty"><i class="bi bi-inbox"></i>${esc(msg)}</div>`;
const loading=()=>`<div class="loading"><i class="bi bi-arrow-repeat"></i> Cargando información…</div>`;
function openModal(title,body,subtitle=''){ $('#modalTitle').textContent=title;$('#modalSubtitle').textContent=subtitle;$('#modalBody').innerHTML=body;$('#modal').classList.remove('hidden'); }
function closeModal(){ $('#modal').classList.add('hidden'); }
function formData(form){return Object.fromEntries(new FormData(form).entries())}
function nullify(o){Object.keys(o).forEach(k=>{if(o[k]==='')o[k]=null});return o}
async function q(table,select='*',builder=x=>x){const {data,error}=await builder(supabase.from(table).select(select));if(error)throw error;return data}
async function catalogs(){const defs=[['estado','id_estado,nombre_estado,activo','id_estado'],['especie','*','id_especie'],['rango_etario','*','id_rango_etario'],['tipo_atencion_sanitaria','*','id_tipo_atencion'],['estado_adopcion','*','id_estado_adopcion'],['categoria_gasto','*','id_categoria_gasto'],['estado_proyecto','*','id_estado_proyecto'],['categoria_archivo','*','id_categoria_archivo']];for(const [t,s,pk] of defs){try{state.catalogs[t]=await q(t,s,x=>x.eq('activo',true).order(pk,{ascending:true}))}catch(e){console.error('Error cargando catálogo',t,e);state.catalogs[t]=[];toast(`No fue posible cargar el catálogo ${t.replaceAll('_',' ')}.`,true)}}}
const options=(arr,id,label,blank='Seleccione…')=>`<option value="">${blank}</option>`+(arr||[]).map(x=>`<option value="${x[id]}">${esc(x[label])}</option>`).join('');
function badgeStatus(s){let c='';if(/Disponible|Adoptado|Finalizado|Activa/i.test(s))c='success';else if(/tratamiento|ejecución|hogar/i.test(s))c='warning';else if(/Devuelto|Cancelado/i.test(s))c='danger';return `<span class="badge ${c}">${esc(s||'Sin estado')}</span>`}
function setHeader(t,s){$('#pageTitle').textContent=t;$('#pageSubtitle').textContent=s||''}
function buildNav(){ $('#nav').innerHTML=nav.map(([id,icon,l])=>`<button class="nav-btn ${state.page===id?'active':''}" data-page="${id}"><i class="bi ${icon}"></i>${l}</button>`).join('');$$('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page)); }
async function go(page){state.page=page;state.selectedAnimal=null;buildNav();$('.sidebar').classList.remove('open');$('#content').innerHTML=loading();try{await pages[page]()}catch(e){fail(e);$('#content').innerHTML=empty('No fue posible cargar esta sección.')}}
async function init(){buildNav();$$('[data-close-modal]').forEach(e=>e.onclick=closeModal);$('#menuBtn').onclick=()=>$('.sidebar').classList.toggle('open');$('#refreshBtn').onclick=()=>go(state.page);$('#logoutBtn').onclick=async()=>{await supabase.auth.signOut();showLogin()};$('#loginForm').onsubmit=login;const {data:{session}}=await supabase.auth.getSession();if(session)await showApp(session.user);else showLogin();supabase.auth.onAuthStateChange(async(e,s)=>{if(e==='SIGNED_OUT')showLogin();if(e==='SIGNED_IN'&&s)await showApp(s.user)});}
function showLogin(){state.user=null;$('#appView').classList.add('hidden');$('#loginView').classList.remove('hidden')}
async function login(e){e.preventDefault();$('#loginError').textContent='';if(!configured){$('#loginError').textContent='Primero configura js/config.js con la URL y clave pública de Supabase.';return}const {error}=await supabase.auth.signInWithPassword({email:$('#loginEmail').value.trim(),password:$('#loginPassword').value});if(error)$('#loginError').textContent='No fue posible iniciar sesión. Revisa correo y contraseña.'}
async function showApp(user){state.user=user;const {data,error}=await supabase.from('usuario').select('*').eq('id_usuario',user.id).single();if(error||!data?.activo){await supabase.auth.signOut();$('#loginError').textContent='La cuenta no está habilitada para usar el sistema.';return}state.profile=data;$('#sidebarUser').textContent=data.nombre;$('#sidebarEmail').textContent=user.email||'';$('#loginView').classList.add('hidden');$('#appView').classList.remove('hidden');await catalogs();go('dashboard')}
async function loadAnimals(){state.animals=await q('animal','*,estado:id_estado_actual(nombre_estado),especie:id_especie(nombre),rango:rango_etario(nombre)',x=>x.eq('activo',true).order('fecha_registro',{ascending:false}));await Promise.all(state.animals.map(async a=>{a._foto_url=null;if(a.foto_principal_path){const {data}=await supabase.storage.from('fotos-animales').createSignedUrl(a.foto_principal_path,3600);a._foto_url=data?.signedUrl||null}}));return state.animals}
const pages={
 dashboard:async()=>{setHeader('Panel principal','Resumen de la situación actual de la Fundación');const a=await loadAnimals();const count=n=>a.filter(x=>x.estado?.nombre_estado===n).length;const health=await q('atencion_sanitaria','id_atencion_sanitaria,proximo_control,tratamiento,animal:id_animal(nombre)',x=>x.not('proximo_control','is',null).gte('proximo_control',new Date().toISOString().slice(0,10)).order('proximo_control').limit(6));const homes=await q('permanencia_animal_hogar','id_permanencia,fecha_ingreso,animal:id_animal(nombre),hogar:id_hogar(nombre_responsable)',x=>x.is('fecha_salida',null).order('fecha_ingreso',{ascending:false}).limit(6));$('#content').innerHTML=`<div class="kpis">${[['Animales activos',a.length,'bi-heart'],['En tratamiento',count('En tratamiento'),'bi-activity'],['En hogar temporal',count('En hogar temporal'),'bi-house-heart'],['Disponibles',count('Disponible para adopción'),'bi-stars'],['Adoptados',count('Adoptado'),'bi-house-check']].map(([l,v,i])=>`<div class="kpi"><div class="kpi-top"><span>${l}</span><span class="kpi-icon"><i class="bi ${i}"></i></span></div><strong>${v}</strong></div>`).join('')}</div><div class="grid-2"><section class="card"><h4>Próximos controles sanitarios</h4>${health.length?health.map(x=>`<div class="list-item"><div><strong>${esc(x.animal?.nombre||'Sin nombre')}</strong><div class="small muted">${esc(x.tratamiento||'Control programado')}</div></div><span class="badge">${fmtDate(x.proximo_control)}</span></div>`).join(''):empty('No hay controles próximos registrados.')}</section><section class="card"><h4>Hogares temporales ocupados</h4>${homes.length?homes.map(x=>`<div class="list-item"><div><strong>${esc(x.animal?.nombre||'Animal')}</strong><div class="small muted">${esc(x.hogar?.nombre_responsable||'Hogar')}</div></div><span class="small muted">Desde ${fmtDate(x.fecha_ingreso)}</span></div>`).join(''):empty('No hay permanencias activas.')}</section></div>`},
 animals:async()=>{setHeader('Animales','Registro central y ficha integral');const a=await loadAnimals();renderAnimals(a)},
 homes:async()=>renderHomes(), adoptions:async()=>renderAdoptions(), expenses:async()=>renderExpenses(), sterilization:async()=>renderProjects(), documents:async()=>renderDocuments(), reports:async()=>renderReports(), settings:async()=>renderSettings()
};
function renderAnimals(list){$('#content').innerHTML=`<div class="page-head"><div><h3>Animales registrados</h3><p>Busca, filtra y abre la ficha integral de cada animal.</p></div><div class="actions"><div class="view-toggle"><button class="icon-btn active" id="cardView" title="Tarjetas"><i class="bi bi-grid-3x2-gap"></i></button><button class="icon-btn" id="listView" title="Lista"><i class="bi bi-list-ul"></i></button></div><button class="btn primary" id="newAnimal"><i class="bi bi-plus-lg"></i> Registrar animal</button></div></div><div class="toolbar"><div class="search-box"><i class="bi bi-search"></i><input id="animalSearch" placeholder="Buscar por nombre, microchip o lugar…"></div><select id="animalState">${options(state.catalogs.estado,'id_estado','nombre_estado','Todos los estados')}</select></div><div id="animalResults" class="animal-grid">${animalCards(list)}</div>`;$('#newAnimal').onclick=animalForm;let mode='cards';const filter=()=>{const s=$('#animalSearch').value.toLowerCase(),st=$('#animalState').value;const f=state.animals.filter(x=>(!s||[x.nombre,x.microchip,x.lugar_rescate].some(v=>String(v||'').toLowerCase().includes(s)))&&(!st||String(x.id_estado_actual)===st));$('#animalResults').className=mode==='cards'?'animal-grid':'animal-list';$('#animalResults').innerHTML=mode==='cards'?animalCards(f):animalRows(f);bindAnimalCards()};$('#animalSearch').oninput=filter;$('#animalState').onchange=filter;$('#cardView').onclick=()=>{mode='cards';$('#cardView').classList.add('active');$('#listView').classList.remove('active');filter()};$('#listView').onclick=()=>{mode='list';$('#listView').classList.add('active');$('#cardView').classList.remove('active');filter()};if(state._pendingAnimalFilter){const f=state._pendingAnimalFilter;state._pendingAnimalFilter=null;if(f==='active'){$('#animalState').value='';const adopted=state.catalogs.estado.find(x=>x.nombre_estado==='Adoptado')?.id_estado;$('#animalResults').innerHTML=animalCards(state.animals.filter(x=>x.id_estado_actual!==adopted));bindAnimalCards()}else if(f==='month'){const m=new Date().toISOString().slice(0,7);$('#animalResults').innerHTML=animalCards(state.animals.filter(x=>(x.fecha_rescate||'').startsWith(m)));bindAnimalCards()}else{const st=state.catalogs.estado.find(x=>x.nombre_estado===f);if(st){$('#animalState').value=st.id_estado;filter()}}}}
function animalCards(a){return a.length?a.map(x=>`<article class="animal-card" data-animal="${x.id_animal}"><div class="animal-photo">${x._foto_url?`<img src="${esc(x._foto_url)}" alt="Foto de ${esc(x.nombre||'animal')}">`:`<i class="bi bi-heart"></i>`}</div><div class="animal-body"><h4>${esc(x.nombre||'Sin nombre')}</h4><div class="small muted">${esc(x.especie?.nombre||'')} · ${esc(x.sexo)}</div><div class="animal-meta">${badgeStatus(x.estado?.nombre_estado)}${x.estado?.nombre_estado==='En hogar temporal'?'<span class="badge success">💚 Disponible para adopción</span>':''}${x.microchip?'<span class="badge brand"><i class="bi bi-upc"></i> Microchip</span>':''}</div></div><span class="card-arrow"><i class="bi bi-chevron-right"></i></span></article>`).join(''):empty('No hay animales que coincidan con los filtros.')}
function bindAnimalCards(){$$('[data-animal]').forEach(e=>e.onclick=()=>animalDetail(+e.dataset.animal))}
function animalForm(){openModal('Registrar animal',`<div class="section-note"><i class="bi bi-info-circle"></i> El estado inicial será <strong>Rescatado</strong> automáticamente.</div><form id="animalForm" class="field-grid"><label>Nombre<input name="p_nombre" maxlength="100"></label><label>Especie<select name="p_id_especie" required>${options(state.catalogs.especie,'id_especie','nombre')}</select></label><label>Rango etario<select name="p_id_rango_etario">${options(state.catalogs.rango_etario,'id_rango_etario','nombre')}</select></label><label>Sexo<select name="p_sexo" required><option>Macho</option><option>Hembra</option><option>Desconocido</option></select></label><label>Tamaño<select name="p_tamano"><option value="">Seleccione…</option><option>Pequeño</option><option>Mediano</option><option>Grande</option></select></label><label>Fecha nacimiento<input type="date" name="p_fecha_nacimiento"></label><label>Fecha rescate<input type="date" name="p_fecha_rescate" required></label><label>Lugar rescate<input name="p_lugar_rescate" maxlength="255"></label><label>Microchip<input name="p_microchip" inputmode="numeric" pattern="[0-9]{15}" maxlength="15" placeholder="15 dígitos"></label><label>Registro Nacional<select name="p_estado_registro_nacional"><option value="">Sin registrar</option><option>Inscrito</option><option>No inscrito</option><option>No verificado</option></select></label><label class="span-2 upload-box"><span><i class="bi bi-camera"></i> Foto principal</span><input type="file" name="foto" accept="image/jpeg,image/png,image/webp"><small>Opcional. Se optimizará a WebP antes de subirla.</small></label><label class="span-2">Características<textarea name="p_caracteristicas"></textarea></label><label class="span-2">Personalidad<textarea name="p_personalidad"></textarea></label><label class="span-2">Historia del rescate<textarea name="p_historia_rescate"></textarea></label><label class="span-2">Observaciones<textarea name="p_observaciones"></textarea></label><div class="form-actions span-2"><button type="button" class="btn" data-close-modal>Cancelar</button><button class="btn primary" data-busy-label="Registrando…"><i class="bi bi-heart-plus"></i> Registrar animal</button></div></form>`);$('[data-close-modal]').onclick=closeModal;$('#animalForm').onsubmit=async e=>{e.preventDefault();if(e.target.dataset.busy)return;const done=setFormBusy(e.target,true,'Registrando animal…');try{const fd=new FormData(e.target),foto=fd.get('foto');const p={};for(const [k,v] of fd.entries())if(k!=='foto')p[k]=v;nullify(p);for(const k of ['p_id_especie','p_id_rango_etario'])p[k]=p[k]?+p[k]:null;const {data:id,error}=await supabase.rpc('registrar_animal',p);if(error)throw error;const folder=await supabase.functions.invoke('crear-carpeta-animal',{body:{id_animal:id}});if(folder.error)console.warn('Carpeta Drive:',folder.error);if(foto instanceof File&&foto.size)await uploadAnimalPhoto(id,foto);closeModal();toast('Animal registrado correctamente.');await go('animals')}catch(err){fail(err);done()} }}
async function animalDetail(id,tab='summary'){const x=(await q('animal','*,estado:id_estado_actual(nombre_estado),especie:id_especie(nombre),rango:rango_etario(nombre)',z=>z.eq('id_animal',id).single()));state.selectedAnimal=x;setHeader(x.nombre||'Ficha animal','Ficha integral y trazabilidad');const tabs=[['summary','Resumen'],['health','Salud'],['homes','Hogares'],['adoption','Adopción'],['expenses','Gastos'],['files','Archivos'],['history','Historial'],['diffusion','Difusión']];$('#content').innerHTML=`<div class="page-head"><button class="btn" id="backAnimals"><i class="bi bi-arrow-left"></i> Animales</button><div class="actions"><button class="btn" id="editAnimal"><i class="bi bi-pencil"></i> Editar ficha</button><button class="btn primary" id="changeState"><i class="bi bi-arrow-repeat"></i> Cambiar estado</button></div></div><section class="card"><div class="profile-head"><div class="profile-photo"><i class="bi bi-heart"></i></div><div><h3>${esc(x.nombre||'Sin nombre')}</h3><div class="muted small">${esc(x.especie?.nombre||'')} · ${esc(x.sexo)} · ${esc(x.rango?.nombre||'Sin rango')}</div><div class="status-row" style="margin-top:9px">${badgeStatus(x.estado?.nombre_estado)}${x.estado?.nombre_estado==='En hogar temporal'?'<span class="badge success">💚 Disponible para adopción</span>':''}</div></div></div><div class="tabs">${tabs.map(([i,l])=>`<button class="tab ${tab===i?'active':''}" data-tab="${i}">${l}</button>`).join('')}</div><div id="animalTab">${loading()}</div></section>`;$('#backAnimals').onclick=()=>go('animals');$('#editAnimal').onclick=()=>editAnimal(x);$('#changeState').onclick=()=>changeState(x);$$('[data-tab]').forEach(b=>b.onclick=()=>animalDetail(id,b.dataset.tab));await renderAnimalTab(x,tab)}
async function renderAnimalTab(x,tab){const box=$('#animalTab');if(tab==='summary')box.innerHTML=`<dl class="definition"><div><dt>Fecha rescate</dt><dd>${fmtDate(x.fecha_rescate)}</dd></div><div><dt>Lugar</dt><dd>${esc(x.lugar_rescate||'—')}</dd></div><div><dt>Microchip</dt><dd>${esc(x.microchip||'No registrado')}</dd></div><div><dt>Registro Nacional</dt><dd>${esc(x.estado_registro_nacional||'No registrado')}</dd></div><div><dt>Tamaño</dt><dd>${esc(x.tamaño||'—')}</dd></div><div><dt>Nacimiento</dt><dd>${fmtDate(x.fecha_nacimiento)}</dd></div></dl><h4>Características</h4><p>${esc(x.caracteristicas||'Sin información.')}</p><h4>Personalidad</h4><p>${esc(x.personalidad||'Sin información.')}</p><h4>Historia del rescate</h4><p>${esc(x.historia_rescate||'Sin información.')}</p>`;
if(tab==='health'){const d=await q('atencion_sanitaria','*,tipo:id_tipo_atencion(nombre)',z=>z.eq('id_animal',x.id_animal).order('fecha',{ascending:false}));box.innerHTML=`<div class="page-head"><h4>Historial sanitario</h4><button class="btn primary" id="addHealth">Registrar atención</button></div>${simpleTable(['Fecha','Tipo','Veterinario','Próximo control'],d.map(r=>[fmtDate(r.fecha),r.tipo?.nombre||'',r.veterinario||'—',fmtDate(r.proximo_control)]))}`;$('#addHealth').onclick=()=>healthForm(x)}
if(tab==='homes'){const d=await q('permanencia_animal_hogar','*,hogar:id_hogar(nombre_responsable)',z=>z.eq('id_animal',x.id_animal).order('fecha_ingreso',{ascending:false}));box.innerHTML=`<div class="page-head"><h4>Permanencias</h4><button class="btn primary" id="homeAction">Gestionar hogar</button></div>${simpleTable(['Hogar','Ingreso','Salida','Observaciones'],d.map(r=>[r.hogar?.nombre_responsable||'',fmtDate(r.fecha_ingreso),fmtDate(r.fecha_salida),r.observaciones||'—']))}`;$('#homeAction').onclick=()=>homeAssignForm(x,d.find(r=>!r.fecha_salida))}
if(tab==='adoption'){const d=await q('adopcion','*,adoptante:id_adoptante(nombre,rut),estado:id_estado_adopcion(nombre)',z=>z.eq('id_animal',x.id_animal).order('fecha_adopcion',{ascending:false}));box.innerHTML=`<div class="page-head"><h4>Adopciones</h4><button class="btn primary" id="adoptAction">Registrar adopción</button></div>${simpleTable(['Fecha','Adoptante','Estado','Finalización'],d.map(r=>[fmtDate(r.fecha_adopcion),r.adoptante?.nombre||'',r.estado?.nombre||'',fmtDate(r.fecha_finalizacion)]))}`;$('#adoptAction').onclick=()=>adoptionForm(x)}
if(tab==='expenses'){const d=await q('animal_gasto','*,gasto:id_gasto(fecha,descripcion,monto)',z=>z.eq('id_animal',x.id_animal).order('id_animal_gasto',{ascending:false}));box.innerHTML=`<h4>Gastos asociados</h4>${simpleTable(['Fecha','Descripción','Asignado','Total gasto'],d.map(r=>[fmtDate(r.gasto?.fecha),r.gasto?.descripcion||'',money(r.monto_asignado),money(r.gasto?.monto)]))}`}
if(tab==='files'){const d=await q('animal_archivo','id_archivo,archivo:id_archivo(*)',z=>z.eq('id_animal',x.id_animal));box.innerHTML=`<div class="page-head"><h4>Archivos</h4><button class="btn primary" id="uploadAnimalFile">Subir archivo</button></div>${fileList(d.map(v=>v.archivo).filter(Boolean))}`;bindFileOpen();$('#uploadAnimalFile').onclick=()=>uploadFileForm('animal',x.id_animal)}
if(tab==='history'){const d=await q('historial_estado','*,estado:id_estado(nombre_estado)',z=>z.eq('id_animal',x.id_animal).order('fecha_inicio',{ascending:false}));box.innerHTML=`<h4>Historial de estados</h4>${simpleTable(['Estado','Inicio','Fin','Motivo'],d.map(r=>[r.estado?.nombre_estado||'',new Date(r.fecha_inicio).toLocaleString('es-CL'),r.fecha_fin?new Date(r.fecha_fin).toLocaleString('es-CL'):'Actual',r.motivo_cambio||'—']))}`}
if(tab==='diffusion'){const txt=`${x.nombre||'Este animal'} busca una familia 💗\n\n${x.historia_rescate||''}\n\n${x.personalidad?`Personalidad: ${x.personalidad}`:''}\n${x.caracteristicas?`Características: ${x.caracteristicas}`:''}\n\nSi quieres conocer más sobre su proceso de adopción, comunícate con Fundación Amor de Cuatro Patas.`;const prompt=`Redacta una publicación para redes sociales destinada a promover la adopción responsable de este animal. Utiliza solamente la información entregada a continuación. Destaca su personalidad, características y situación de forma cercana, positiva y respetuosa. No inventes datos que no estén registrados.\n\nNombre: ${x.nombre||'Sin nombre'}\nEspecie: ${x.especie?.nombre||'No indicada'}\nPersonalidad: ${x.personalidad||'No indicada'}\nCaracterísticas: ${x.caracteristicas||'No indicadas'}\nHistoria de rescate: ${x.historia_rescate||'No indicada'}`;box.innerHTML=`<div class="grid-2"><div><h4>Texto base para difusión</h4><p class="small muted">Contenido editable para una publicación rápida.</p><textarea id="diffText" style="min-height:260px">${esc(txt)}</textarea><div class="form-actions"><button class="btn primary" id="copyDiff"><i class="bi bi-copy"></i> Copiar texto</button></div></div><div><h4>Prompt base para IA</h4><p class="small muted">Versión inicial. La ajustaremos después de validar el tono con la Fundación.</p><textarea id="diffPrompt" style="min-height:260px">${esc(prompt)}</textarea><div class="form-actions"><button class="btn" id="copyPrompt"><i class="bi bi-copy"></i> Copiar prompt</button></div></div></div>`;$('#copyDiff').onclick=async()=>{await navigator.clipboard.writeText($('#diffText').value);toast('Texto copiado.')};$('#copyPrompt').onclick=async()=>{await navigator.clipboard.writeText($('#diffPrompt').value);toast('Prompt copiado.')}}}
function editAnimal(x){openModal('Editar ficha',`<div class="section-note">El estado no se modifica aquí. Para eso se utiliza <strong>Cambiar estado</strong>.</div><form id="editAnimalForm" class="field-grid"><label>Nombre<input name="nombre" value="${esc(x.nombre||'')}"></label><label>Rango etario<select name="id_rango_etario">${options(state.catalogs.rango_etario,'id_rango_etario','nombre')}</select></label><label>Sexo<select name="sexo"><option>Macho</option><option>Hembra</option><option>Desconocido</option></select></label><label>Tamaño<select name="tamaño"><option value="">Seleccione…</option><option>Pequeño</option><option>Mediano</option><option>Grande</option></select></label><label>Microchip<input name="microchip" value="${esc(x.microchip||'')}" pattern="[0-9]{15}" maxlength="15"></label><label>Registro Nacional<select name="estado_registro_nacional"><option value="">Sin registrar</option><option>Inscrito</option><option>No inscrito</option><option>No verificado</option></select></label><label class="span-2">Características<textarea name="caracteristicas">${esc(x.caracteristicas||'')}</textarea></label><label class="span-2">Personalidad<textarea name="personalidad">${esc(x.personalidad||'')}</textarea></label><label class="span-2">Observaciones<textarea name="observaciones">${esc(x.observaciones||'')}</textarea></label><div class="form-actions span-2"><button class="btn primary">Guardar cambios</button></div></form>`);const f=$('#editAnimalForm');f.id_rango_etario.value=x.id_rango_etario||'';f.sexo.value=x.sexo;f.tamaño.value=x.tamaño||'';f.estado_registro_nacional.value=x.estado_registro_nacional||'';f.onsubmit=async e=>{e.preventDefault();try{const p=nullify(formData(f));p.id_rango_etario=p.id_rango_etario?+p.id_rango_etario:null;const {error}=await supabase.from('animal').update(p).eq('id_animal',x.id_animal);if(error)throw error;closeModal();toast('Ficha actualizada.');animalDetail(x.id_animal)}catch(err){fail(err)}}}
function changeState(x){const allowed=state.catalogs.estado.filter(s=>!['En hogar temporal','Adoptado'].includes(s.nombre_estado));openModal('Cambiar estado',`<form id="stateForm" class="field-grid"><label class="span-2">Nuevo estado<select name="p_id_nuevo_estado" required>${options(allowed,'id_estado','nombre_estado')}</select></label><label class="span-2">Motivo<textarea name="p_motivo_cambio"></textarea></label><label class="span-2">Observaciones<textarea name="p_observaciones"></textarea></label><div class="form-actions span-2"><button class="btn primary">Confirmar cambio</button></div></form>`);$('#stateForm').onsubmit=async e=>{e.preventDefault();try{const p=nullify(formData(e.target));p.p_id_animal=x.id_animal;p.p_id_nuevo_estado=+p.p_id_nuevo_estado;const {error}=await supabase.rpc('cambiar_estado_animal',p);if(error)throw error;closeModal();toast('Estado actualizado.');animalDetail(x.id_animal)}catch(err){fail(err)}}}
function healthForm(x){openModal('Registrar atención sanitaria',`<form id="healthForm" class="field-grid"><label>Tipo<select name="id_tipo_atencion" required>${options(state.catalogs.tipo_atencion_sanitaria,'id_tipo_atencion','nombre')}</select></label><label>Fecha<input type="date" name="fecha" required></label><label>Veterinario<input name="veterinario"></label><label>Próximo control<input type="date" name="proximo_control"></label><label class="span-2">Tratamiento<textarea name="tratamiento"></textarea></label><label class="span-2">Medicamento<textarea name="medicamento"></textarea></label><label class="span-2">Observaciones<textarea name="observaciones"></textarea></label><div class="form-actions span-2"><button class="btn primary">Guardar</button></div></form>`);$('#healthForm').onsubmit=async e=>{e.preventDefault();try{const p=nullify(formData(e.target));p.id_animal=x.id_animal;p.id_tipo_atencion=+p.id_tipo_atencion;const {error}=await supabase.from('atencion_sanitaria').insert(p);if(error)throw error;closeModal();toast('Atención registrada.');animalDetail(x.id_animal,'health')}catch(err){fail(err)}}}
async function homeAssignForm(x,current){const homes=await q('hogar_temporal','*',z=>z.eq('activo',true).order('nombre_responsable'));if(current){openModal('Gestionar hogar temporal',`<p>El animal tiene una permanencia activa.</p><div class="actions"><button class="btn" id="switchHome">Cambiar de hogar</button><button class="btn primary" id="finishHome">Finalizar permanencia</button></div>`);$('#switchHome').onclick=()=>homeRpcForm('cambiar_hogar_temporal',x,homes,current);$('#finishHome').onclick=()=>homeFinishForm(x)}else homeRpcForm('ingresar_hogar_temporal',x,homes)}
function homeRpcForm(rpc,x,homes){openModal(rpc==='ingresar_hogar_temporal'?'Ingresar a hogar temporal':'Cambiar hogar temporal',`<form id="homeRpc" class="field-grid"><label class="span-2">Hogar<select name="home" required>${options(homes,'id_hogar','nombre_responsable')}</select></label>${!homes.length?'<div class="section-note span-2">No hay hogares activos todavía. Puedes crear uno ahora mismo.</div>':''}<label>Fecha<input type="date" name="date" required value="${new Date().toISOString().slice(0,10)}"></label><label class="span-2">Observaciones<textarea name="obs"></textarea></label><div class="form-actions span-2"><button type="button" class="btn" id="quickHome"><i class="bi bi-house-add"></i> Nuevo hogar</button><button class="btn primary" ${homes.length?'':'disabled'}>Guardar</button></div></form>`);$('#quickHome').onclick=()=>homeEditForm(null,()=>homeAssignForm(x,null));$('#homeRpc').onsubmit=async e=>{e.preventDefault();if(e.target.dataset.busy)return;const d=formData(e.target),done=setFormBusy(e.target,true,'Guardando…');const p=rpc==='ingresar_hogar_temporal'?{p_id_animal:x.id_animal,p_id_hogar:+d.home,p_fecha_ingreso:d.date,p_observaciones:d.obs||null}:{p_id_animal:x.id_animal,p_id_nuevo_hogar:+d.home,p_fecha_cambio:d.date,p_observaciones:d.obs||null};const {error}=await supabase.rpc(rpc,p);if(error){fail(error);done();return}closeModal();toast('Hogar actualizado.');animalDetail(x.id_animal,'homes')}}
function homeFinishForm(x){const allowed=state.catalogs.estado.filter(s=>!['En hogar temporal','Adoptado'].includes(s.nombre_estado));openModal('Finalizar hogar temporal',`<form id="finishHomeForm" class="field-grid"><label>Fecha salida<input type="date" name="p_fecha_salida" required></label><label>Nuevo estado<select name="p_id_nuevo_estado" required>${options(allowed,'id_estado','nombre_estado')}</select></label><label class="span-2">Observaciones<textarea name="p_observaciones"></textarea></label><div class="form-actions span-2"><button class="btn primary">Finalizar</button></div></form>`);$('#finishHomeForm').onsubmit=async e=>{e.preventDefault();const p=nullify(formData(e.target));p.p_id_animal=x.id_animal;p.p_id_nuevo_estado=+p.p_id_nuevo_estado;const {error}=await supabase.rpc('finalizar_hogar_temporal',p);if(error)return fail(error);closeModal();toast('Permanencia finalizada.');animalDetail(x.id_animal,'homes')}}
async function adoptionForm(x){const adopters=await q('adoptante','*',z=>z.order('nombre'));openModal('Registrar adopción',`<form id="adoptionForm" class="field-grid"><label class="span-2">Adoptante<select name="p_id_adoptante" required>${options(adopters,'id_adoptante','nombre')}</select></label><label>Fecha adopción<input type="date" name="p_fecha_adopcion" required></label><label class="span-2">Observaciones<textarea name="p_observaciones"></textarea></label><div class="form-actions span-2"><button type="button" class="btn" id="quickAdopter">Nuevo adoptante</button><button class="btn primary">Registrar adopción</button></div></form>`);$('#quickAdopter').onclick=()=>adopterForm(()=>adoptionForm(x));$('#adoptionForm').onsubmit=async e=>{e.preventDefault();const p=nullify(formData(e.target));p.p_id_animal=x.id_animal;p.p_id_adoptante=+p.p_id_adoptante;const {error}=await supabase.rpc('registrar_adopcion',p);if(error)return fail(error);closeModal();toast('Adopción registrada.');animalDetail(x.id_animal,'adoption')}}
function adopterForm(after){openModal('Nuevo adoptante',`<form id="adopterForm" class="field-grid"><label>Nombre<input name="nombre" required></label><label>RUT<input name="rut" required></label><label>Teléfono<input name="telefono"></label><label>Email<input type="email" name="email"></label><label class="span-2">Dirección<textarea name="direccion"></textarea></label><label class="span-2">Observaciones<textarea name="observaciones"></textarea></label><div class="form-actions span-2"><button class="btn primary">Guardar adoptante</button></div></form>`);$('#adopterForm').onsubmit=async e=>{e.preventDefault();const {error}=await supabase.from('adoptante').insert(nullify(formData(e.target)));if(error)return fail(error);toast('Adoptante registrado.');after?after():go('adoptions')}}
async function renderHomes(){setHeader('Hogares temporales','Red de hogares y ocupación actual');const h=await q('hogar_temporal','*',z=>z.order('nombre_responsable'));const p=await q('permanencia_animal_hogar','id_hogar,id_animal,animal:id_animal(nombre)',z=>z.is('fecha_salida',null));$('#content').innerHTML=`<div class="page-head"><div><h3>Hogares temporales</h3><p>Administra hogares y asigna animales sin salir del módulo.</p></div><button class="btn primary" id="newHome"><i class="bi bi-house-add"></i> Nuevo hogar</button></div><div class="home-grid">${h.length?h.map(x=>{const occ=p.filter(v=>v.id_hogar===x.id_hogar);return `<article class="card home-card"><div class="section-title"><span class="section-icon"><i class="bi bi-house-heart"></i></span><div><h4>${esc(x.nombre_responsable)}</h4><p>${esc([x.telefono,x.email].filter(Boolean).join(' · ')||'Sin contacto')}</p></div></div><p class="small"><i class="bi bi-geo-alt"></i> ${esc(x.direccion||'Sin dirección')}</p><div class="occupants"><strong>${occ.length} animal${occ.length===1?'':'es'} actualmente</strong><span>${esc(occ.map(v=>v.animal?.nombre).filter(Boolean).join(', ')||'Sin animales')}</span></div><div class="form-actions"><button class="btn" data-edit-home="${x.id_hogar}"><i class="bi bi-pencil"></i> Editar</button><button class="btn primary" data-add-home-animal="${x.id_hogar}" ${x.activo?'':'disabled'}><i class="bi bi-plus-lg"></i> Asignar animal</button></div></article>`}).join(''):empty('Aún no hay hogares temporales. Registra el primero para comenzar.')}</div>`;$('#newHome').onclick=()=>homeEditForm();$$('[data-edit-home]').forEach(b=>b.onclick=()=>homeEditForm(h.find(x=>x.id_hogar==b.dataset.editHome)));$$('[data-add-home-animal]').forEach(b=>b.onclick=()=>assignAnimalToHome(+b.dataset.addHomeAnimal))}
async function renderAdoptions(){setHeader('Adopciones','Adopciones, adoptantes y seguimientos');const a=await q('adopcion','*,animal:id_animal(nombre),adoptante:id_adoptante(nombre,rut),estado:id_estado_adopcion(nombre)',z=>z.order('fecha_adopcion',{ascending:false}));const ad=await q('adoptante','*',z=>z.order('nombre'));$('#content').innerHTML=`<div class="tabs"><button class="tab active" data-a="a">Adopciones</button><button class="tab" data-a="b">Adoptantes</button></div><div id="adoptionArea">${adoptionTable(a)}</div>`;$$('[data-a]').forEach(b=>b.onclick=()=>{$$('[data-a]').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#adoptionArea').innerHTML=b.dataset.a==='a'?adoptionTable(a):`<div class="page-head"><h4>Adoptantes</h4><button class="btn primary" id="newAdopter">Nuevo adoptante</button></div>${simpleTable(['Nombre','RUT','Teléfono','Email'],ad.map(x=>[x.nombre,x.rut,x.telefono||'—',x.email||'—']))}`;if(b.dataset.a==='b')$('#newAdopter').onclick=()=>adopterForm()});bindAdoptionRows()}
function adoptionTable(a){return `<h4>Adopciones registradas</h4>${simpleTable(['Animal','Adoptante','Fecha','Estado','Acciones'],a.map(x=>[x.animal?.nombre||'',x.adoptante?.nombre||'',fmtDate(x.fecha_adopcion),x.estado?.nombre||'',`<button class="btn" data-follow="${x.id_adopcion}">Seguimiento</button>`]))}`}
function bindAdoptionRows(){$$('[data-follow]').forEach(b=>b.onclick=()=>followForm(+b.dataset.follow))}
function followForm(id){openModal('Registrar seguimiento',`<form id="followForm" class="field-grid"><label>Fecha<input type="date" name="p_fecha" required></label><label>Medio<select name="p_medio_contacto" required><option value="WhatsApp">WhatsApp</option><option value="Telefono">Teléfono</option><option value="Correo">Correo electrónico</option><option value="Visita">Visita</option><option value="Otro">Otro</option></select></label><label class="span-2">Situación del animal<textarea name="p_situacion_animal"></textarea></label><label class="span-2">Observaciones<textarea name="p_observaciones"></textarea></label><div class="form-actions span-2"><button class="btn primary">Guardar seguimiento</button></div></form>`);$('#followForm').onsubmit=async e=>{e.preventDefault();if(e.target.dataset.busy)return;const done=setFormBusy(e.target,true,'Guardando…');try{const p=nullify(formData(e.target));p.p_id_adopcion=id;const {error}=await supabase.rpc('registrar_seguimiento',p);if(error)throw error;closeModal();toast('Seguimiento registrado.');go('adoptions')}catch(err){fail(err);done()}}}
async function renderExpenses(){setHeader('Gastos','Registro y distribución de gastos');const g=await q('gasto','*,categoria:id_categoria_gasto(nombre),animal_gasto(monto_asignado,animal:id_animal(nombre))',z=>z.order('fecha',{ascending:false}));$('#content').innerHTML=`<div class="page-head"><div><h3>Gastos</h3><p>Un gasto puede distribuirse entre uno o varios animales sin superar su total.</p></div><button class="btn primary" id="newExpense">Registrar gasto</button></div>${simpleTable(['Fecha','Categoría','Descripción','Monto','Asignado'],g.map(x=>[fmtDate(x.fecha),x.categoria?.nombre||'',x.descripcion,money(x.monto),money((x.animal_gasto||[]).reduce((s,v)=>s+v.monto_asignado,0))]))}`;$('#newExpense').onclick=expenseForm}
async function expenseForm(){const animals=await loadAnimals();openModal('Registrar gasto',`<form id="expenseForm" class="field-grid"><label>Categoría<select name="id_categoria_gasto" required>${options(state.catalogs.categoria_gasto,'id_categoria_gasto','nombre')}</select></label><label>Fecha<input type="date" name="fecha" required></label><label class="span-2">Descripción<input name="descripcion" required></label><label>Monto total<input type="number" name="monto" min="1" step="1" required></label><label>Tipo<select id="expenseType"><option value="general">Gasto general</option><option value="animals">Asignar a animal(es)</option></select></label><label class="span-2">Observaciones<textarea name="observaciones"></textarea></label><div id="expenseAnimals" class="span-2 hidden"><div class="section-note">Puedes distribuir el gasto entre uno o varios animales. La suma no puede superar el total.</div>${animals.map(a=>`<div class="allocation-row"><label><input type="checkbox" data-exp-animal="${a.id_animal}"> ${esc(a.nombre||'Sin nombre')}</label><input type="number" min="1" step="1" placeholder="Monto" data-exp-amount="${a.id_animal}" disabled></div>`).join('')}</div><div class="form-actions span-2"><button class="btn primary">Guardar gasto</button></div></form>`);$('#expenseType').onchange=e=>$('#expenseAnimals').classList.toggle('hidden',e.target.value!=='animals');$$('[data-exp-animal]').forEach(c=>c.onchange=()=>{const i=$(`[data-exp-amount="${c.dataset.expAnimal}"]`);i.disabled=!c.checked;if(!c.checked)i.value='' });$('#expenseForm').onsubmit=async e=>{e.preventDefault();if(e.target.dataset.busy)return;const done=setFormBusy(e.target,true,'Guardando gasto…');try{const fd=new FormData(e.target);const p={id_categoria_gasto:+fd.get('id_categoria_gasto'),fecha:fd.get('fecha'),descripcion:fd.get('descripcion'),monto:+fd.get('monto'),observaciones:fd.get('observaciones')||null};const allocations=$$('[data-exp-animal]:checked').map(c=>({id:+c.dataset.expAnimal,monto:+$(`[data-exp-amount="${c.dataset.expAnimal}"]`).value}));if($('#expenseType').value==='animals'){if(!allocations.length)throw new Error('Selecciona al menos un animal.');if(allocations.some(x=>!x.monto||x.monto<=0))throw new Error('Ingresa el monto asignado a cada animal.');if(allocations.reduce((s,x)=>s+x.monto,0)>p.monto)throw new Error('La suma asignada no puede superar el total del gasto.')}const {data:g,error}=await supabase.from('gasto').insert(p).select('id_gasto').single();if(error)throw error;for(const a of allocations){const r=await supabase.rpc('asignar_gasto_animal',{p_id_gasto:g.id_gasto,p_id_animal:a.id,p_monto_asignado:a.monto});if(r.error)throw r.error}closeModal();toast('Gasto registrado correctamente.');go('expenses')}catch(err){fail(err);done()}}}
async function renderProjects(){setHeader('Proyectos de esterilización','Gestión separada de campañas y nóminas');const p=await q('proyecto_esterilizacion','*,estado:id_estado_proyecto(nombre),animal_esterilizacion(count)',z=>z.order('id_proyecto',{ascending:false}));$('#content').innerHTML=`<div class="page-head"><div><h3>Proyectos</h3><p>Información, nómina, profesionales y documentación por proyecto.</p></div><button class="btn primary" id="newProject">Nuevo proyecto</button></div>${simpleTable(['Proyecto','Estado','Inicio','Fin','Responsable'],p.map(x=>[x.nombre,x.estado?.nombre||'',fmtDate(x.fecha_inicio),fmtDate(x.fecha_fin),`<button class="btn" data-project="${x.id_proyecto}">Abrir</button>`]))}`;$('#newProject').onclick=projectForm;$$('[data-project]').forEach(b=>b.onclick=()=>projectDetail(+b.dataset.project))}
async function projectDetail(id,tab='info'){const p=await q('proyecto_esterilizacion','*,estado:id_estado_proyecto(nombre)',z=>z.eq('id_proyecto',id).single());const animals=await q('animal_esterilizacion','*,especie:id_especie(nombre),rango:id_rango_etario(nombre),esterilizacion_profesional(funcion,profesional:id_profesional(id_profesional,nombre,profesion)),esterilizacion_archivo(id_archivo,archivo:id_archivo(*))',z=>z.eq('id_proyecto',id).order('codigo'));const projectFiles=await q('proyecto_archivo','id_archivo,archivo:id_archivo(*)',z=>z.eq('id_proyecto',id));setHeader(p.nombre,'Detalle del proyecto de esterilización');const tabs=[['info','Información','bi-info-circle'],['roster','Nómina','bi-list-check'],['pros','Profesionales','bi-person-badge'],['docs','Documentación','bi-folder2-open']];$('#content').innerHTML=`<div class="page-head"><button class="btn" id="backProjects"><i class="bi bi-arrow-left"></i> Proyectos</button><button class="btn primary" id="addSterAnimal"><i class="bi bi-plus-lg"></i> Agregar a nómina</button></div><section class="card"><div class="project-hero"><div><span class="eyebrow">Proyecto de esterilización</span><h3>${esc(p.nombre)}</h3><div class="status-row">${badgeStatus(p.estado?.nombre)}</div></div><div class="project-count"><strong>${animals.length}</strong><span>animales en nómina</span></div></div><div class="tabs">${tabs.map(([k,l,i])=>`<button class="tab ${tab===k?'active':''}" data-project-tab="${k}"><i class="bi ${i}"></i> ${l}</button>`).join('')}</div><div id="projectTab"></div></section>`;$('#backProjects').onclick=()=>go('sterilization');$('#addSterAnimal').onclick=()=>sterAnimalForm(p,animals);$$('[data-project-tab]').forEach(b=>b.onclick=()=>projectDetail(id,b.dataset.projectTab));const box=$('#projectTab');if(tab==='info')box.innerHTML=`<dl class="definition"><div><dt>Responsable</dt><dd>${esc(p.responsable||'—')}</dd></div><div><dt>Entidad financiante</dt><dd>${esc(p.entidad_financiante||'—')}</dd></div><div><dt>Postulación</dt><dd>${fmtDate(p.fecha_postulacion)}</dd></div><div><dt>Inicio</dt><dd>${fmtDate(p.fecha_inicio)}</dd></div><div><dt>Fin</dt><dd>${fmtDate(p.fecha_fin)}</dd></div></dl><h4>Descripción</h4><p>${esc(p.descripcion||'Sin descripción.')}</p>`;if(tab==='roster'){box.innerHTML=`<div class="page-head"><div><h4>Nómina del proyecto</h4><p class="small muted">El documento individual puede abrirse directamente desde cada animal.</p></div></div>${sterRosterTable(animals)}`;bindFileOpen()}if(tab==='pros'){const map=new Map();animals.forEach(a=>(a.esterilizacion_profesional||[]).forEach(r=>{const pr=r.profesional;if(pr){const v=map.get(pr.id_profesional)||{...pr,count:0,functions:new Set()};v.count++;v.functions.add(r.funcion);map.set(pr.id_profesional,v)}}));box.innerHTML=map.size?`<div class="professional-grid">${[...map.values()].map(pr=>`<article class="mini-card"><span class="section-icon pink"><i class="bi bi-person-badge"></i></span><div><h4>${esc(pr.nombre)}</h4><p>${esc(pr.profesion)} · ${pr.count} participación${pr.count===1?'':'es'}</p><small>${esc([...pr.functions].join(', '))}</small></div></article>`).join('')}</div>`:empty('Los profesionales aparecerán aquí al asociarlos a animales de la nómina.')}if(tab==='docs'){box.innerHTML=`<div class="page-head"><div><h4>Documentación general del proyecto</h4><p class="small muted">Convenios, informes, rendiciones u otros antecedentes.</p></div><button class="btn primary" id="uploadProject"><i class="bi bi-cloud-arrow-up"></i> Subir documento</button></div>${fileList(projectFiles.map(x=>x.archivo).filter(Boolean))}`;bindFileOpen();$('#uploadProject').onclick=()=>uploadFileForm('proyecto',id,()=>projectDetail(id,'docs'))}}
async function sterAnimalForm(p,existing=[]){const pros=await q('profesional','*',z=>z.order('nombre'));const next=Math.max(0,...existing.map(a=>Number(String(a.codigo||'').match(/(\d+)$/)?.[1]||0)))+1;const suggested=`EST-${String(next).padStart(3,'0')}`;openModal('Agregar animal a nómina',`<div class="section-note"><i class="bi bi-lightbulb"></i> El código se sugiere automáticamente y puedes cambiarlo si la Fundación usa otra numeración.</div><form id="sterAnimalForm" class="field-grid"><label>Código interno<input name="codigo" required value="${suggested}"></label><label>Especie<select name="id_especie" required>${options(state.catalogs.especie,'id_especie','nombre')}</select></label><label>Rango etario<select name="id_rango_etario">${options(state.catalogs.rango_etario,'id_rango_etario','nombre')}</select></label><label>Sexo<select name="sexo" required><option>Macho</option><option>Hembra</option><option>Desconocido</option></select></label><label>Microchip<input name="microchip" pattern="[0-9]{15}" maxlength="15"></label><label>Registro Nacional<select name="estado_registro_nacional"><option value="">Sin registrar</option><option>Inscrito</option><option>No inscrito</option><option>No verificado</option></select></label><label>Fecha nacimiento<input type="date" name="fecha_nacimiento"></label><label>Sector origen<input name="sector_origen"></label><label>Fecha esterilización<input type="date" name="fecha_esterilizacion"></label><label>Lugar esterilización<input name="lugar_esterilizacion"></label><label class="span-2">Características<textarea name="caracteristicas"></textarea></label><label class="span-2">Observaciones<textarea name="observaciones"></textarea></label><div class="span-2 subform"><h4><i class="bi bi-person-badge"></i> Profesional</h4><div class="field-grid"><label>Profesional<select name="id_profesional">${options(pros,'id_profesional','nombre','Sin asociar por ahora')}</select></label><label>Función<input name="funcion" placeholder="Ej. Médico veterinario"></label></div><button type="button" class="btn small-btn" id="quickProfessional"><i class="bi bi-plus-lg"></i> Registrar nuevo profesional</button></div><label class="span-2 upload-box"><span><i class="bi bi-file-earmark-pdf"></i> Documento de esterilización (PDF)</span><input type="file" name="documento" accept="application/pdf" required><small>Se guardará en la carpeta Animales del proyecto y quedará asociado a este registro.</small></label><div class="form-actions span-2"><button class="btn primary"><i class="bi bi-check-lg"></i> Agregar a nómina</button></div></form>`);$('#quickProfessional').onclick=()=>professionalQuickForm(()=>sterAnimalForm(p,existing));$('#sterAnimalForm').onsubmit=async e=>{e.preventDefault();if(e.target.dataset.busy)return;const done=setFormBusy(e.target,true,'Guardando animal y documento…');try{const fd=new FormData(e.target),doc=fd.get('documento'),proId=fd.get('id_profesional'),funcion=fd.get('funcion');if(!(doc instanceof File)||!doc.size)throw new Error('Debes adjuntar el documento PDF de esterilización.');if(doc.type!=='application/pdf')throw new Error('El documento de esterilización debe ser PDF.');if(proId&&!funcion)throw new Error('Indica la función del profesional seleccionado.');const d={};for(const [k,v] of fd.entries())if(!['documento','id_profesional','funcion'].includes(k))d[k]=v;nullify(d);d.id_proyecto=p.id_proyecto;d.id_especie=+d.id_especie;d.id_rango_etario=d.id_rango_etario?+d.id_rango_etario:null;const ins=await supabase.from('animal_esterilizacion').insert(d).select('id_animal_esterilizacion').single();if(ins.error)throw ins.error;const id=ins.data.id_animal_esterilizacion;if(proId){const rel=await supabase.from('esterilizacion_profesional').insert({id_animal_esterilizacion:id,id_profesional:+proId,funcion});if(rel.error)throw rel.error}const cat=state.catalogs.categoria_archivo.find(c=>/esteriliz/i.test(c.nombre))||state.catalogs.categoria_archivo[0];if(!cat)throw new Error('No existe una categoría de archivo activa para registrar el PDF.');const up=new FormData();up.append('archivo',doc);up.append('id_categoria_archivo',cat.id_categoria_archivo);up.append('tipo_contexto','esterilizacion');up.append('id_contexto',String(id));up.append('fecha_documento',d.fecha_esterilizacion||'');up.append('descripcion',`Documento de esterilización ${d.codigo}`);const ur=await supabase.functions.invoke('subir-archivo-drive',{body:up});if(ur.error)throw ur.error;if(ur.data?.error)throw new Error(ur.data.error);closeModal();toast('Animal, profesional y documento registrados.');projectDetail(p.id_proyecto,'roster')}catch(err){fail(err);done()}}}
function projectForm(){openModal('Nuevo proyecto de esterilización',`<form id="projectForm" class="field-grid"><label class="span-2">Nombre<input name="nombre" required></label><label>Estado<select name="id_estado_proyecto" required>${options(state.catalogs.estado_proyecto,'id_estado_proyecto','nombre')}</select></label><label>Fecha postulación<input type="date" name="fecha_postulacion"></label><label>Fecha inicio<input type="date" name="fecha_inicio"></label><label>Fecha fin<input type="date" name="fecha_fin"></label><label>Responsable<input name="responsable"></label><label>Entidad financiante<input name="entidad_financiante"></label><label class="span-2">Descripción<textarea name="descripcion"></textarea></label><label class="span-2">Observaciones<textarea name="observaciones"></textarea></label><div class="form-actions span-2"><button class="btn primary">Crear proyecto</button></div></form>`);$('#projectForm').onsubmit=async e=>{e.preventDefault();const p=nullify(formData(e.target));p.id_estado_proyecto=+p.id_estado_proyecto;const {data,error}=await supabase.from('proyecto_esterilizacion').insert(p).select('id_proyecto').single();if(error)return fail(error);await supabase.functions.invoke('crear-carpeta-proyecto',{body:{id_proyecto:data.id_proyecto}}).catch(console.warn);closeModal();toast('Proyecto creado.');go('sterilization')}}
async function renderDocuments(){setHeader('Documentos','Buscador transversal de archivos almacenados en Google Drive');const d=await q('archivo','*,categoria:id_categoria_archivo(nombre)',z=>z.order('fecha_carga',{ascending:false}));$('#content').innerHTML=`<div class="toolbar"><input id="docSearch" placeholder="Buscar documento…"><select id="docCat">${options(state.catalogs.categoria_archivo,'id_categoria_archivo','nombre','Todas las categorías')}</select></div><div id="docArea">${documentTable(d)}</div>`;const f=()=>{const s=$('#docSearch').value.toLowerCase(),c=$('#docCat').value;$('#docArea').innerHTML=documentTable(d.filter(x=>(!s||[x.nombre_archivo,x.nombre_original,x.descripcion].some(v=>String(v||'').toLowerCase().includes(s)))&&(!c||String(x.id_categoria_archivo)===c)));bindFileOpen()};$('#docSearch').oninput=f;$('#docCat').onchange=f;bindFileOpen()}
function documentTable(d){return simpleTable(['Nombre','Categoría','Fecha documento','Acción'],d.map(x=>[x.nombre_original||x.nombre_archivo,x.categoria?.nombre||'',fmtDate(x.fecha_documento),`<button class="btn" data-open-file="${x.id_archivo}"><i class="bi bi-box-arrow-up-right"></i> Abrir</button>`]))}
function fileList(d){return d.length?documentTable(d):empty('No hay archivos asociados.')}
function bindFileOpen(){$$('[data-open-file]').forEach(b=>b.onclick=async()=>{if(b.disabled)return;const old=b.innerHTML;b.disabled=true;b.innerHTML='<span class="spinner"></span> Abriendo…';try{const {data,error}=await supabase.functions.invoke('obtener-link-archivo',{body:{id_archivo:+b.dataset.openFile}});if(error)throw error;const url=data?.archivo?.url||data?.url||data?.webViewLink||data?.link;if(!url)throw new Error(data?.error||'La función no devolvió un enlace.');window.open(url,'_blank','noopener')}catch(e){fail(e)}finally{b.disabled=false;b.innerHTML=old}})}
function uploadFileForm(context,id,after){openModal('Subir archivo a Google Drive',`<form id="uploadForm" class="field-grid"><label class="span-2 upload-box">Archivo<input type="file" name="archivo" required></label><label>Categoría<select name="id_categoria_archivo" required>${options(state.catalogs.categoria_archivo,'id_categoria_archivo','nombre')}</select></label><label>Fecha documento<input type="date" name="fecha_documento"></label><label class="span-2">Descripción<textarea name="descripcion"></textarea></label><div class="upload-status span-2 hidden" id="uploadStatus"><span class="spinner"></span><div><strong>Subiendo a Google Drive…</strong><small>No cierres esta ventana mientras termina.</small></div></div><div class="form-actions span-2"><button class="btn primary">Subir archivo</button></div></form>`);$('#uploadForm').onsubmit=async e=>{e.preventDefault();if(e.target.dataset.busy)return;const done=setFormBusy(e.target,true,'Subiendo…');$('#uploadStatus').classList.remove('hidden');try{const fd=new FormData(e.target);fd.append('tipo_contexto',context);if(id!=null)fd.append('id_contexto',String(id));const {data,error}=await supabase.functions.invoke('subir-archivo-drive',{body:fd});if(error)throw error;if(data?.error)throw new Error(data.error);closeModal();toast('Archivo cargado correctamente.');if(after)await after();else if(context==='animal')await animalDetail(id,'files');else await go(state.page)}catch(err){fail(err);done();$('#uploadStatus').classList.add('hidden')}}}
async function renderReports(){setHeader('Informes','Construye consultas según la información que necesites');const reports=[['Animales','Estado, especie, sexo y fecha de rescate','animals-state','bi-heart'],['Adopciones','Adopciones por período','adoptions','bi-house-check'],['Atenciones sanitarias','Atenciones y próximos controles','health','bi-activity'],['Hogares temporales','Permanencias activas e históricas','homes','bi-house-heart'],['Gastos','Gastos por período y categoría','expenses','bi-cash-stack'],['Esterilizaciones','Nómina por proyecto y período','sterilized','bi-clipboard2-pulse']];$('#content').innerHTML=`<div class="report-intro card"><div><h3>Informes configurables</h3><p>Selecciona un informe y ajusta sus filtros. Los campos disponibles cambian según el tipo de consulta.</p></div><i class="bi bi-sliders"></i></div><div class="report-grid">${reports.map(([t,d,k,i])=>`<div class="report-card" data-report="${k}"><i class="bi ${i}"></i><h4>${t}</h4><p>${d}</p></div>`).join('')}</div><div id="reportArea" style="margin-top:18px"></div>`;$$('[data-report]').forEach(e=>e.onclick=()=>reportFilters(e.dataset.report))}
async function runReport(k){const area=$('#reportArea');area.innerHTML=loading();let headers=[],rows=[];if(k==='animals-state'){const a=await loadAnimals();headers=['Estado','Cantidad'];rows=state.catalogs.estado.map(s=>[s.nombre_estado,a.filter(x=>x.id_estado_actual===s.id_estado).length])}if(k==='rescues'){const d=await q('animal','nombre,fecha_rescate,lugar_rescate,especie:id_especie(nombre)',z=>z.order('fecha_rescate',{ascending:false}));headers=['Animal','Especie','Fecha rescate','Lugar'];rows=d.map(x=>[x.nombre||'Sin nombre',x.especie?.nombre||'',fmtDate(x.fecha_rescate),x.lugar_rescate||'—'])}if(k==='adoptions'){const d=await q('adopcion','fecha_adopcion,animal:id_animal(nombre),adoptante:id_adoptante(nombre),estado:id_estado_adopcion(nombre)',z=>z.order('fecha_adopcion',{ascending:false}));headers=['Animal','Adoptante','Fecha','Estado'];rows=d.map(x=>[x.animal?.nombre||'',x.adoptante?.nombre||'',fmtDate(x.fecha_adopcion),x.estado?.nombre||''])}if(k==='health'){const d=await q('atencion_sanitaria','fecha,veterinario,tratamiento,proximo_control,animal:id_animal(nombre),tipo:id_tipo_atencion(nombre)',z=>z.order('fecha',{ascending:false}));headers=['Animal','Tipo','Fecha','Veterinario','Próximo control'];rows=d.map(x=>[x.animal?.nombre||'',x.tipo?.nombre||'',fmtDate(x.fecha),x.veterinario||'—',fmtDate(x.proximo_control)])}if(k==='homes'){const d=await q('permanencia_animal_hogar','fecha_ingreso,fecha_salida,animal:id_animal(nombre),hogar:id_hogar(nombre_responsable)',z=>z.order('fecha_ingreso',{ascending:false}));headers=['Animal','Hogar','Ingreso','Salida'];rows=d.map(x=>[x.animal?.nombre||'',x.hogar?.nombre_responsable||'',fmtDate(x.fecha_ingreso),fmtDate(x.fecha_salida)])}if(k==='expenses'){const d=await q('gasto','fecha,descripcion,monto,categoria:id_categoria_gasto(nombre)',z=>z.order('fecha',{ascending:false}));headers=['Fecha','Categoría','Descripción','Monto'];rows=d.map(x=>[fmtDate(x.fecha),x.categoria?.nombre||'',x.descripcion,money(x.monto)])}if(k==='projects'){const d=await q('proyecto_esterilizacion','nombre,fecha_inicio,fecha_fin,responsable,estado:id_estado_proyecto(nombre)',z=>z.order('id_proyecto',{ascending:false}));headers=['Proyecto','Estado','Inicio','Fin','Responsable'];rows=d.map(x=>[x.nombre,x.estado?.nombre||'',fmtDate(x.fecha_inicio),fmtDate(x.fecha_fin),x.responsable||'—'])}if(k==='sterilized'){const d=await q('animal_esterilizacion','codigo,microchip,sexo,fecha_esterilizacion,proyecto:id_proyecto(nombre),especie:id_especie(nombre)',z=>z.order('id_animal_esterilizacion',{ascending:false}));headers=['Proyecto','Código','Microchip','Especie','Sexo','Fecha'];rows=d.map(x=>[x.proyecto?.nombre||'',x.codigo,x.microchip||'—',x.especie?.nombre||'',x.sexo,fmtDate(x.fecha_esterilizacion)])}area.innerHTML=`<div class="page-head"><h3>Resultado</h3><div class="actions"><button class="btn" id="csvBtn">Exportar CSV</button><button class="btn" onclick="window.print()">Imprimir / PDF</button></div></div>${simpleTable(headers,rows)}`;$('#csvBtn').onclick=()=>downloadCSV(headers,rows)}
function downloadCSV(h,r){const clean=v=>`"${String(v??'').replace(/<[^>]+>/g,'').replaceAll('"','""')}"`;const csv='\ufeff'+[h,...r].map(row=>row.map(clean).join(';')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='informe_amor_de_cuatro_patas.csv';a.click();URL.revokeObjectURL(a.href)}
async function renderSettings(){setHeader('Configuración','Cuenta, usuarios y catálogos');const users=await q('usuario','*',z=>z.order('nombre'));$('#content').innerHTML=`<div class="grid-2"><section class="card"><div class="section-title"><span class="section-icon"><i class="bi bi-person"></i></span><div><h4>Mi cuenta</h4><p>Datos de la sesión actual.</p></div></div><dl class="definition"><div><dt>Nombre</dt><dd>${esc(state.profile.nombre)}</dd></div><div><dt>Email</dt><dd>${esc(state.user.email||'')}</dd></div></dl><div class="form-actions"><button class="btn" id="passwordBtn">Cambiar contraseña</button></div></section><section class="card"><div class="page-head"><div><h4>Usuarios</h4><p class="small muted">Accesos autorizados al sistema.</p></div><button class="btn primary" id="inviteBtn">Invitar usuaria</button></div>${simpleTable(['Nombre','Estado','Acción'],users.map(u=>[u.nombre,u.activo?'Activo':'Inactivo',u.id_usuario===state.user.id?'Cuenta actual':`<button class="btn" data-user-toggle="${u.id_usuario}" data-active="${u.activo}">${u.activo?'Desactivar':'Activar'}</button>`]))}</section></div><section class="card" style="margin-top:18px"><div class="page-head"><div><h4>Catálogos del sistema</h4><p class="small muted">Agrega, edita o activa/desactiva opciones utilizadas por formularios y filtros.</p></div></div><div class="catalog-grid">${[['especie','Especies'],['rango_etario','Rangos etarios'],['tipo_atencion_sanitaria','Tipos de atención'],['categoria_gasto','Categorías de gasto'],['estado_proyecto','Estados de proyecto'],['categoria_archivo','Categorías de archivo']].map(([k,l])=>`<button class="catalog-card" data-catalog="${k}"><i class="bi bi-tags"></i><span>${l}</span><small>${state.catalogs[k]?.length||0} activos</small></button>`).join('')}</div></section>`;$('#inviteBtn').onclick=inviteForm;$('#passwordBtn').onclick=passwordForm;$$('[data-user-toggle]').forEach(b=>b.onclick=async()=>{const rpc=b.dataset.active==='true'?'desactivar_usuario':'activar_usuario';const {error}=await supabase.rpc(rpc,{p_id_usuario:b.dataset.userToggle});if(error)return fail(error);toast('Usuario actualizado.');go('settings')});$$('[data-catalog]').forEach(b=>b.onclick=()=>catalogManager(b.dataset.catalog))}
function inviteForm(){openModal('Invitar usuaria',`<form id="inviteForm" class="field-grid"><label>Nombre<input name="nombre" required></label><label>Email<input type="email" name="email" required></label><div class="form-actions span-2"><button class="btn primary">Enviar invitación</button></div></form>`);$('#inviteForm').onsubmit=async e=>{e.preventDefault();const {data,error}=await supabase.functions.invoke('invitar-usuario',{body:formData(e.target)});if(error)return fail(error);closeModal();toast(data?.message||'Invitación enviada.')}}
function passwordForm(){openModal('Cambiar contraseña',`<form id="passForm"><label>Nueva contraseña<input type="password" name="password" minlength="8" required></label><div class="form-actions"><button class="btn primary">Actualizar contraseña</button></div></form>`);$('#passForm').onsubmit=async e=>{e.preventDefault();const {error}=await supabase.auth.updateUser({password:new FormData(e.target).get('password')});if(error)return fail(error);closeModal();toast('Contraseña actualizada.')}}
function genericInsert(title,table,fields,after){openModal(title,`<form id="genericForm" class="field-grid">${fields.map(([n,l,t='text',req=false])=>`<label class="${t==='textarea'?'span-2':''}">${l}${t==='textarea'?`<textarea name="${n}" ${req?'required':''}></textarea>`:`<input type="${t}" name="${n}" ${req?'required':''}>`}</label>`).join('')}<div class="form-actions span-2"><button class="btn primary">Guardar</button></div></form>`);$('#genericForm').onsubmit=async e=>{e.preventDefault();const {error}=await supabase.from(table).insert(nullify(formData(e.target)));if(error)return fail(error);closeModal();toast('Registro guardado.');after()}}
function simpleTable(headers,rows){if(!rows.length)return empty();return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${typeof c==='string'&&c.includes('<button')?c:esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function sterRosterTable(animals){if(!animals.length)return empty('Aún no hay animales en la nómina.');return `<div class="table-wrap"><table><thead><tr><th>Código</th><th>Microchip</th><th>Especie</th><th>Sexo</th><th>Fecha</th><th>Profesional</th><th>Documento</th></tr></thead><tbody>${animals.map(a=>{const prs=(a.esterilizacion_profesional||[]).map(r=>`${r.profesional?.nombre||''}${r.funcion?` · ${r.funcion}`:''}`).filter(Boolean).join('<br>')||'—';const file=(a.esterilizacion_archivo||[])[0]?.archivo;return `<tr><td><strong>${esc(a.codigo)}</strong></td><td>${esc(a.microchip||'—')}</td><td>${esc(a.especie?.nombre||'')}</td><td>${esc(a.sexo)}</td><td>${fmtDate(a.fecha_esterilizacion)}</td><td>${prs}</td><td>${file?`<button class="btn" data-open-file="${file.id_archivo}"><i class="bi bi-file-earmark-pdf"></i> Abrir PDF</button>`:'—'}</td></tr>`}).join('')}</tbody></table></div>`}
function professionalQuickForm(after){openModal('Registrar profesional',`<form id="quickProForm" class="field-grid"><label>Nombre<input name="nombre" required></label><label>Profesión<input name="profesion" required></label><label>Teléfono<input name="telefono"></label><label>Email<input type="email" name="email"></label><label class="span-2">Observaciones<textarea name="observaciones"></textarea></label><div class="form-actions span-2"><button class="btn primary">Guardar profesional</button></div></form>`);$('#quickProForm').onsubmit=async e=>{e.preventDefault();const done=setFormBusy(e.target,true,'Guardando…');const {error}=await supabase.from('profesional').insert(nullify(formData(e.target)));if(error){fail(error);done();return}toast('Profesional registrado.');after()}}
function setFormBusy(form,busy=true,label='Procesando…'){const buttons=[...form.querySelectorAll('button')],inputs=[...form.querySelectorAll('input,select,textarea')];if(busy){form.dataset.busy='1';buttons.forEach(b=>{b.dataset.oldHtml=b.innerHTML;b.disabled=true});inputs.forEach(i=>i.disabled=true);const submit=form.querySelector('button[type="submit"],button:not([type])');if(submit)submit.innerHTML=`<span class="spinner"></span> ${label}`}return()=>{delete form.dataset.busy;buttons.forEach(b=>{b.disabled=false;if(b.dataset.oldHtml){b.innerHTML=b.dataset.oldHtml;delete b.dataset.oldHtml}});inputs.forEach(i=>i.disabled=false)}}
function openAnimalsFromDashboard(filter){state._pendingAnimalFilter=filter;go('animals')}
function animalRows(a){return a.length?`<div class="table-wrap"><table><thead><tr><th>Animal</th><th>Especie</th><th>Sexo</th><th>Estado</th><th>Microchip</th><th></th></tr></thead><tbody>${a.map(x=>`<tr class="click-row" data-animal="${x.id_animal}"><td><div class="mini-animal">${x._foto_url?`<img src="${esc(x._foto_url)}">`:`<span><i class="bi bi-heart"></i></span>`}<strong>${esc(x.nombre||'Sin nombre')}</strong></div></td><td>${esc(x.especie?.nombre||'—')}</td><td>${esc(x.sexo)}</td><td>${badgeStatus(x.estado?.nombre_estado)}</td><td>${esc(x.microchip||'—')}</td><td><i class="bi bi-chevron-right"></i></td></tr>`).join('')}</tbody></table></div>`:empty('No hay animales que coincidan con los filtros.')}
async function imageToWebp(file,max=1400,quality=.82){if(file.type==='image/webp'&&file.size<2*1024*1024)return file;const bitmap=await createImageBitmap(file);const scale=Math.min(1,max/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const blob=await new Promise((res,rej)=>canvas.toBlob(b=>b?res(b):rej(new Error('No fue posible optimizar la imagen.')),'image/webp',quality));if(blob.size>2*1024*1024)throw new Error('La foto optimizada supera 2 MB. Prueba con otra imagen.');return new File([blob],'principal.webp',{type:'image/webp'})}
async function uploadAnimalPhoto(id,file){const webp=await imageToWebp(file),path=`animales/${id}/principal.webp`;const {error}=await supabase.storage.from('fotos-animales').upload(path,webp,{contentType:'image/webp',upsert:true});if(error)throw error;const u=await supabase.from('animal').update({foto_principal_path:path}).eq('id_animal',id);if(u.error)throw u.error;return path}
async function homeEditForm(home=null,after){openModal(home?'Editar hogar temporal':'Nuevo hogar temporal',`<form id="homeEdit" class="field-grid"><label>Responsable<input name="nombre_responsable" required value="${esc(home?.nombre_responsable||'')}"></label><label>Teléfono<input name="telefono" value="${esc(home?.telefono||'')}"></label><label>Email<input type="email" name="email" value="${esc(home?.email||'')}"></label><label>Estado<select name="activo"><option value="true">Activo</option><option value="false">Inactivo</option></select></label><label class="span-2">Dirección<textarea name="direccion">${esc(home?.direccion||'')}</textarea></label><label class="span-2">Observaciones<textarea name="observaciones">${esc(home?.observaciones||'')}</textarea></label><div class="form-actions span-2"><button class="btn primary">${home?'Guardar cambios':'Crear hogar'}</button></div></form>`);$('#homeEdit').activo.value=String(home?.activo??true);$('#homeEdit').onsubmit=async e=>{e.preventDefault();if(e.target.dataset.busy)return;const done=setFormBusy(e.target,true,'Guardando…');try{const d=nullify(formData(e.target));d.activo=d.activo==='true';let r;if(home)r=await supabase.from('hogar_temporal').update(d).eq('id_hogar',home.id_hogar).select().single();else r=await supabase.from('hogar_temporal').insert(d).select().single();if(r.error)throw r.error;closeModal();toast(home?'Hogar actualizado.':'Hogar creado.');after?after(r.data):go('homes')}catch(err){fail(err);done()}}}
async function assignAnimalToHome(idHome){const animals=(await loadAnimals()).filter(a=>a.estado?.nombre_estado!=='Adoptado'&&a.estado?.nombre_estado!=='En hogar temporal');openModal('Asignar animal al hogar',`<form id="assignHome" class="field-grid"><label class="span-2">Animal<select name="animal" required>${options(animals,'id_animal','nombre')}</select></label><label>Fecha ingreso<input type="date" name="fecha" required value="${new Date().toISOString().slice(0,10)}"></label><label class="span-2">Observaciones<textarea name="obs"></textarea></label><div class="form-actions span-2"><button class="btn primary">Asignar animal</button></div></form>`);$('#assignHome').onsubmit=async e=>{e.preventDefault();const d=formData(e.target);const done=setFormBusy(e.target,true,'Asignando…');const {error}=await supabase.rpc('ingresar_hogar_temporal',{p_id_animal:+d.animal,p_id_hogar:idHome,p_fecha_ingreso:d.fecha,p_observaciones:d.obs||null});if(error){fail(error);done();return}closeModal();toast('Animal asignado al hogar.');go('homes')}}
async function createHomeAndAssign(x){await homeEditForm(null,async home=>{const {error}=await supabase.rpc('ingresar_hogar_temporal',{p_id_animal:x.id_animal,p_id_hogar:home.id_hogar,p_fecha_ingreso:new Date().toISOString().slice(0,10),p_observaciones:null});if(error)return fail(error);toast('Hogar creado y animal asignado.');animalDetail(x.id_animal,'homes')})}
async function reportFilters(k){const area=$('#reportArea');const common=`<label>Desde<input type="date" id="rfFrom"></label><label>Hasta<input type="date" id="rfTo"></label>`;let extra='';if(k==='animals-state')extra=`<label>Especie<select id="rfSpecies">${options(state.catalogs.especie,'id_especie','nombre','Todas')}</select></label><label>Estado<select id="rfState">${options(state.catalogs.estado,'id_estado','nombre_estado','Todos')}</select></label><label>Sexo<select id="rfSex"><option value="">Todos</option><option>Macho</option><option>Hembra</option><option>Desconocido</option></select></label>`;if(k==='expenses')extra=`<label>Categoría<select id="rfCategory">${options(state.catalogs.categoria_gasto,'id_categoria_gasto','nombre','Todas')}</select></label>`;if(k==='sterilized'){const projects=await q('proyecto_esterilizacion','id_proyecto,nombre',z=>z.order('nombre'));extra=`<label>Proyecto<select id="rfProject">${options(projects,'id_proyecto','nombre','Todos')}</select></label><label>Especie<select id="rfSpecies">${options(state.catalogs.especie,'id_especie','nombre','Todas')}</select></label>`}area.innerHTML=`<section class="card"><div class="page-head"><div><h3>Filtros del informe</h3><p>Ajusta solo lo que necesites consultar.</p></div></div><div class="filter-grid">${common}${extra}<div class="form-actions"><button class="btn primary" id="runFiltered"><i class="bi bi-search"></i> Consultar</button></div></div><div id="filteredResult"></div></section>`;$('#runFiltered').onclick=()=>runFilteredReport(k)}
async function runFilteredReport(k){const target=$('#filteredResult');target.innerHTML=loading();const from=$('#rfFrom')?.value,to=$('#rfTo')?.value;let headers=[],rows=[];if(k==='animals-state'){let z=supabase.from('animal').select('nombre,sexo,fecha_rescate,estado:id_estado_actual(nombre_estado),especie:id_especie(nombre)');if(from)z=z.gte('fecha_rescate',from);if(to)z=z.lte('fecha_rescate',to);if($('#rfSpecies')?.value)z=z.eq('id_especie',+$('#rfSpecies').value);if($('#rfState')?.value)z=z.eq('id_estado_actual',+$('#rfState').value);if($('#rfSex')?.value)z=z.eq('sexo',$('#rfSex').value);const {data,error}=await z.order('fecha_rescate',{ascending:false});if(error)return fail(error);headers=['Animal','Especie','Sexo','Estado','Rescate'];rows=data.map(x=>[x.nombre||'Sin nombre',x.especie?.nombre||'',x.sexo,x.estado?.nombre_estado||'',fmtDate(x.fecha_rescate)])}else if(k==='adoptions'){let z=supabase.from('adopcion').select('fecha_adopcion,animal:id_animal(nombre),adoptante:id_adoptante(nombre),estado:id_estado_adopcion(nombre)');if(from)z=z.gte('fecha_adopcion',from);if(to)z=z.lte('fecha_adopcion',to);const {data,error}=await z.order('fecha_adopcion',{ascending:false});if(error)return fail(error);headers=['Animal','Adoptante','Fecha','Estado'];rows=data.map(x=>[x.animal?.nombre||'',x.adoptante?.nombre||'',fmtDate(x.fecha_adopcion),x.estado?.nombre||''])}else if(k==='health'){let z=supabase.from('atencion_sanitaria').select('fecha,veterinario,proximo_control,animal:id_animal(nombre),tipo:id_tipo_atencion(nombre)');if(from)z=z.gte('fecha',from);if(to)z=z.lte('fecha',to);const {data,error}=await z.order('fecha',{ascending:false});if(error)return fail(error);headers=['Animal','Tipo','Fecha','Veterinario','Próximo control'];rows=data.map(x=>[x.animal?.nombre||'',x.tipo?.nombre||'',fmtDate(x.fecha),x.veterinario||'—',fmtDate(x.proximo_control)])}else if(k==='homes'){let z=supabase.from('permanencia_animal_hogar').select('fecha_ingreso,fecha_salida,animal:id_animal(nombre),hogar:id_hogar(nombre_responsable)');if(from)z=z.gte('fecha_ingreso',from);if(to)z=z.lte('fecha_ingreso',to);const {data,error}=await z.order('fecha_ingreso',{ascending:false});if(error)return fail(error);headers=['Animal','Hogar','Ingreso','Salida'];rows=data.map(x=>[x.animal?.nombre||'',x.hogar?.nombre_responsable||'',fmtDate(x.fecha_ingreso),fmtDate(x.fecha_salida)])}else if(k==='expenses'){let z=supabase.from('gasto').select('fecha,descripcion,monto,categoria:id_categoria_gasto(nombre)');if(from)z=z.gte('fecha',from);if(to)z=z.lte('fecha',to);if($('#rfCategory')?.value)z=z.eq('id_categoria_gasto',+$('#rfCategory').value);const {data,error}=await z.order('fecha',{ascending:false});if(error)return fail(error);headers=['Fecha','Categoría','Descripción','Monto'];rows=data.map(x=>[fmtDate(x.fecha),x.categoria?.nombre||'',x.descripcion,money(x.monto)])}else if(k==='sterilized'){let z=supabase.from('animal_esterilizacion').select('codigo,microchip,sexo,fecha_esterilizacion,proyecto:id_proyecto(nombre),especie:id_especie(nombre)');if(from)z=z.gte('fecha_esterilizacion',from);if(to)z=z.lte('fecha_esterilizacion',to);if($('#rfProject')?.value)z=z.eq('id_proyecto',+$('#rfProject').value);if($('#rfSpecies')?.value)z=z.eq('id_especie',+$('#rfSpecies').value);const {data,error}=await z.order('fecha_esterilizacion',{ascending:false});if(error)return fail(error);headers=['Proyecto','Código','Microchip','Especie','Sexo','Fecha'];rows=data.map(x=>[x.proyecto?.nombre||'',x.codigo,x.microchip||'—',x.especie?.nombre||'',x.sexo,fmtDate(x.fecha_esterilizacion)])}target.innerHTML=`<div class="result-head"><strong>${rows.length} resultado${rows.length===1?'':'s'}</strong><div class="actions"><button class="btn" id="csvFiltered">Exportar CSV</button><button class="btn" onclick="window.print()">Imprimir / PDF</button></div></div>${simpleTable(headers,rows)}`;$('#csvFiltered').onclick=()=>downloadCSV(headers,rows)}
async function catalogManager(key){const cfg={especie:['Especies','id_especie','nombre'],rango_etario:['Rangos etarios','id_rango_etario','nombre'],tipo_atencion_sanitaria:['Tipos de atención','id_tipo_atencion','nombre'],categoria_gasto:['Categorías de gasto','id_categoria_gasto','nombre'],estado_proyecto:['Estados de proyecto','id_estado_proyecto','nombre'],categoria_archivo:['Categorías de archivo','id_categoria_archivo','nombre']}[key];if(!cfg)return;const [title,pk,label]=cfg;const data=await q(key,'*',z=>z.order(pk));openModal(title,`<div class="page-head"><p class="small muted">Los registros históricos no se eliminan; puedes activar o desactivar opciones.</p><button class="btn primary" id="newCatalog">Agregar</button></div><div id="catalogRows">${simpleTable(['Nombre','Estado','Acción'],data.map(x=>[x[label],x.activo?'Activo':'Inactivo',`<button class="btn" data-cat-edit="${x[pk]}">Editar</button>`]))}</div>`);$('#newCatalog').onclick=()=>catalogEdit(key,cfg,null);$$('[data-cat-edit]').forEach(b=>b.onclick=()=>catalogEdit(key,cfg,data.find(x=>x[pk]==b.dataset.catEdit)))}
function catalogEdit(key,cfg,row){const [title,pk,label]=cfg;openModal(`${row?'Editar':'Agregar'} · ${title}`,`<form id="catForm" class="field-grid"><label class="span-2">Nombre<input name="${label}" required value="${esc(row?.[label]||'')}"></label><label class="span-2">Descripción<textarea name="descripcion">${esc(row?.descripcion||'')}</textarea></label><label>Estado<select name="activo"><option value="true">Activo</option><option value="false">Inactivo</option></select></label><div class="form-actions span-2"><button class="btn primary">Guardar</button></div></form>`);$('#catForm').activo.value=String(row?.activo??true);$('#catForm').onsubmit=async e=>{e.preventDefault();const d=nullify(formData(e.target));d.activo=d.activo==='true';const r=row?await supabase.from(key).update(d).eq(pk,row[pk]):await supabase.from(key).insert(d);if(r.error)return fail(r.error);await catalogs();toast('Catálogo actualizado.');catalogManager(key)}}
init().catch(fail);
